    /* 1. Validate Configuration */
    int config_valid = 1;
    if (rs_config.enable != 0 && rs_config.enable != 1) config_valid = 0;
    if (rs_config.max_residual_rad < 0.0) config_valid = 0;
    if (rs_config.fuse_angle_rad < 0.0 || rs_config.fuse_angle_rad > ADCS_PI) config_valid = 0;
    if (rs_config.switch_margin_rad < 0.0) config_valid = 0;
    if (rs_config.residual_weight_floor_rad <= 0.0) config_valid = 0;
    if (rs_config.output_alpha <= 0.0 || rs_config.output_alpha > 1.0) config_valid = 0;
    if (rs_config.switch_confirm_cycles < 1U || rs_config.switch_confirm_cycles > 20U) config_valid = 0;
    if (rs_config.max_outage_cycles < 1U || rs_config.max_outage_cycles > 20U) config_valid = 0;

    if (!config_valid) {
        rs_output.source = RS_FAULT;
        rs_output.primary = rs_state.primary;
        rs_output.candidate = rs_state.candidate;
        rs_output.candidate_good = rs_state.candidate_good;
        rs_output.outage = rs_state.outage;
        rs_output.disagreement_rad = 0.0;
        rs_output.star_weight = 0.0;
        rs_output.triad_weight = 0.0;
        rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
        return;
    }

    /* 2. Check Source Usability */
    adcs_quat_t star_normed, triad_normed;
    int star_usable = 0;
    int triad_usable = 0;
    double star_resid = rs_input.star_residual_rad;
    double triad_resid = rs_input.triad_residual_rad;

    if (isfinite(star_resid) && star_resid >= 0.0 && star_resid <= rs_config.max_residual_rad) {
        if (adcs_quat_normalize(rs_input.star_q_bi, &star_normed) == ADCS_OK) {
            star_usable = 1;
        }
    }

    if (isfinite(triad_resid) && triad_resid >= 0.0 && triad_resid <= rs_config.max_residual_rad) {
        if (adcs_quat_normalize(rs_input.triad_q_bi, &triad_normed) == ADCS_OK) {
            triad_usable = 1;
        }
    }

    /* 3. Primary/Candidate Selection Logic */
    rs_source_t new_primary = rs_state.primary;
    rs_source_t new_candidate = rs_state.candidate;
    unint32 new_candidate_good = rs_state.candidate_good;

    // Determine initial roles if no primary held
    if (rs_state.primary == RS_NONE) {
        if (star_usable) {
            new_primary = RS_STAR;
            new_candidate = RS_TRIAD;
        } else if (triad_usable) {
            new_primary = RS_TRIAD;
            new_candidate = RS_STAR;
        } else {
            new_primary = RS_NONE;
            new_candidate = RS_NONE;
        }
    } else {
        new_primary = rs_state.primary;
        new_candidate = rs_state.candidate;

        // If current primary lost, switch immediately to other usable
        int primary_usable = (new_primary == RS_STAR) ? star_usable : triad_usable;
        if (!primary_usable) {
            if (new_candidate == RS_STAR && star_usable) {
                new_primary = RS_STAR;
            } else if (new_candidate == RS_TRIAD && triad_usable) {
                new_primary = RS_TRIAD;
            } else {
                new_primary = RS_NONE;
                new_candidate = RS_NONE;
            }
        }

        // Switch confirmation logic if both usable
        if (star_usable && triad_usable) {
            int alt_is_better = 0;
            double primary_res = (new_primary == RS_STAR) ? star_resid : triad_resid;
            double alt_res = (new_primary == RS_STAR) ? triad_resid : star_resid;

            if (alt_res < primary_res - rs_config.switch_margin_rad) {
                alt_is_better = 1;
            }

            if (alt_is_better) {
                new_candidate_good++;
                if (new_candidate_good >= rs_config.switch_confirm_cycles) {
                    rs_source_t temp = new_primary;
                    new_primary = new_candidate;
                    new_candidate = temp;
                    new_candidate_good = 0; 
                }
            } else {
                new_candidate_good = 0;
            }
        } else {
            new_candidate_good = 0;
        }
    }

    rs_state.primary = new_primary;
    rs_state.candidate = new_candidate;
    rs_state.candidate_good = new_candidate_good;

    /* 4. Fusion or Primary Publication */
    adcs_quat_t selected_q_bi;
    rs_source_t output_source_type = RS_NONE;

    if (new_primary == RS_STAR) {
        selected_q_bi = star_normed;
    } else if (new_primary == RS_TRIAD) {
        selected_q_bi = triad_normed;
    } else {
        output_source_type = RS_NONE;
        goto publish_none;
    }

    if (star_usable && triad_usable) {
        double abs_dot = fabs(adcs_quat_abs_dot(&star_normed, &triad_normed));
        if (abs_dot > 1.0) abs_dot = 1.0;
        if (abs_dot < -1.0) abs_dot = -1.0;
        double disc_agr_rad = 2.0 * acos(abs_dot);

        if (disc_agr_rad <= rs_config.fuse_angle_rad) {
            adcs_quat_t aligned_triad = triad_normed;
            double real_dot = star_normed.w * triad_normed.w + star_normed.x * triad_normed.x + 
                              star_normed.y * triad_normed.y + star_normed.z * triad_normed.z;
            if (real_dot < 0.0) {
                 aligned_triad.w = -triad_normed.w;
                 aligned_triad.x = -triad_normed.x;
                 aligned_triad.y = -triad_normed.y;
                 aligned_triad.z = -triad_normed.z;
            }

            double w_star = 1.0 / (rs_config.residual_weight_floor_rad + star_resid);
            double w_triad = 1.0 / (rs_config.residual_weight_floor_rad + triad_resid);

            adcs_quat_t sum_q;
            sum_q.w = w_star * star_normed.w + w_triad * aligned_triad.w;
            sum_q.x = w_star * star_normed.x + w_triad * aligned_triad.x;
            sum_q.y = w_star * star_normed.y + w_triad * aligned_triad.y;
            sum_q.z = w_star * star_normed.z + w_triad * aligned_triad.z;

            adcs_status_t st = adcs_quat_normalize(&sum_q, &selected_q_bi);
            if (st != ADCS_OK) {
                selected_q_bi = star_normed;
            }

            output_source_type = RS_FUSED;
            rs_output.disagreement_rad = disc_agr_rad;
            rs_output.star_weight = w_star;
            rs_output.triad_weight = w_triad;
        } else {
            output_source_type = rs_state.primary;
            rs_output.disagreement_rad = disc_agr_rad;
            rs_output.star_weight = 0.0;
            rs_output.triad_weight = 0.0;
        }
    } else {
        output_source_type = rs_state.primary;
        rs_output.disagreement_rad = 0.0;
        rs_output.star_weight = 0.0;
        rs_output.triad_weight = 0.0;
    }

    /* 5. Output Blending and Normalization */
    adcs_quat_t blended_q;
    double real_dot_prev = rs_state.previous_q_bi.w * selected_q_bi.w + 
                           rs_state.previous_q_bi.x * selected_q_bi.x + 
                           rs_state.previous_q_bi.y * selected_q_bi.y + 
                           rs_state.previous_q_bi.z * selected_q_bi.z;

    adcs_quat_t align_selected = selected_q_bi;
    if (real_dot_prev < 0.0) {
        align_selected.w = -selected_q_bi.w;
        align_selected.x = -selected_q_bi.x;
        align_selected.y = -selected_q_bi.y;
        align_selected.z = -selected_q_bi.z;
    }

    blended_q.w = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.w + rs_config.output_alpha * align_selected.w;
    blended_q.x = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.x + rs_config.output_alpha * align_selected.x;
    blended_q.y = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.y + rs_config.output_alpha * align_selected.y;
    blended_q.z = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.z + rs_config.output_alpha * align_selected.z;

    adcs_status_t norm_st = adcs_quat_normalize(&blended_q, &rs_output.q_bi);
    if (norm_st != ADCS_OK) {
        rs_output.q_bi = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
    }

    rs_state.previous_q_bi = rs_output.q_bi;

publish_none:
    if (output_source_type == RS_NONE) {
        rs_output.source = RS_NONE;
        rs_output.outage++;
        rs_output.primary = rs_state.primary;
        rs_output.candidate = rs_state.candidate;
        rs_output.candidate_good = rs_state.candidate_good;
        rs_output.disagreement_rad = 0.0;
        rs_output.star_weight = 0.0;
        rs_output.triad_weight = 0.0;
    } else {
        rs_output.source = output_source_type;
        rs_output.outage = 0;
        rs_output.primary = rs_state.primary;
        rs_output.candidate = rs_state.candidate;
        rs_output.candidate_good = rs_state.candidate_good;
    }

