    adcs_quat_t blended_q;
    double real_dot_prev = rs_state.previous_q_bi.w * selected_q_bi.w + 
                           rs_state.previous_q_bi.x * selected_q_bi.x + 
                           rs_state.previous_q_bi.y * selected_q_bi.y + 
                           rs_state.previous_q_bi.z * selected_q_bi.z;

