        align_selected.x = -selected_q_bi.x;
        align_selected.y = -selected_q_bi.y;
        align_selected.z = -selected_q_bi.z;
    }

    blended_q.w = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.w + rs_config.output_alpha * align_selected.w;
