    rs_input.star_residual_rad >= 0.0 && rs_input.star_residual_rad <= rs_config.max_residual_rad) {
    if (adcs_quat_normalize(rs_input.star_q_bi, &star_norm) == ADCS_OK) {
        star_usable = 1;
    }
