    if (!triad_usable) {
        if (star_usable) {
            rs_state.primary = RS_STAR;
        }
    } else {
        if (star_usable) {
            if (rs_input.star_residual_rad + rs_config.switch_margin_rad < rs_input.triad_residual_rad) {
                rs_state.candidate_good++;
                if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
                    rs_state.primary = RS_STAR;
