adcs_quat_t selected_q_bi = {0};
rs_source_t final_source = RS_NONE;

double w_s = 0.0;
double w_t = 0.0;
double disc_agreement = 0.0;

if (star_usable && triad_usable) {
    double abs_d = adcs_quat_abs_dot(&star_norm, &triad_norm);
    if (abs_d > 1.0) abs_d = 1.0;
    disc_agreement = acos(abs_d);

    w_s = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.star_residual_rad);
    w_t = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.triad_residual_rad);

    if (disc_agreement <= rs_config.fuse_angle_rad) {
        final_source = RS_FUSED;
        adcs_quat_t triad_aligned = triad_norm;
        double signed_dot = star_norm.w * triad_norm.w + star_norm.x * triad_norm.x + 
                            star_norm.y * triad_norm.y + star_norm.z * triad_norm.z;
        if (signed_dot < 0.0) {
            triad_aligned = (adcs_quat_t){-triad_norm.w, -triad_norm.x, -triad_norm.y, -triad_norm.z};
        }

        adcs_quat_t scaled_star = (adcs_quat_t){w_s * star_norm.w, w_s * star_norm.x, w_s * star_norm.y, w_s * star_norm.z};
        adcs_quat_t scaled_triad = (adcs_quat_t){w_t * triad_aligned.w, w_t * triad_aligned.x, w_t * triad_aligned.y, w_t * triad_aligned.z};

        adcs_quat_t sum_q = (adcs_quat_t){scaled_star.w + scaled_triad.w, 
                                          scaled_star.x + scaled_triad.x, 
                                          scaled_star.y + scaled_triad.y, 
                                          scaled_star.z + scaled_triad.z};
        (void)adcs_quat_normalize(&sum_q, &selected_q_bi);
    } else {
        if (rs_state.primary == RS_STAR) {
            final_source = RS_STAR;
            selected_q_bi = star_norm;
        } else {
            final_source = RS_TRIAD;
            selected_q_bi = triad_norm;
