                                  (1.0 - rs_config.output_alpha) * aligned_prev.y,
                                  (1.0 - rs_config.output_alpha) * aligned_prev.z};
adcs_quat_t term2 = (adcs_quat_t){rs_config.output_alpha * selected_q_bi.w,
                                  rs_config.output_alpha * selected_q_bi.x,
                                  rs_config.output_alpha * selected_q_bi.y,
                                  rs_config.output_alpha * selected_q_bi.z};

adcs_quat_t result_raw = (adcs_quat_t){term1.w + term2.w,
                                       term1.x + term2.x,
                                       term1.y + term2.y,
                                       term1.z + term2.z};

(void)adcs_quat_normalize(&result_raw, &rs_output.q_bi);

rs_state.previous_q_bi = rs_output.q_bi;

