                          star_normed.y * triad_normed.y + star_normed.z * triad_normed.z;
        adcs_quat_t aligned_triad = triad_normed;
        if (dot_prod < 0) {
            aligned_triad.w = -aligned_triad.w;
            aligned_triad.x = -aligned_triad.x;
            aligned_triad.y = -aligned_triad.y;
            aligned_triad.z = -aligned_triad.z;
