        double w_star = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.star_residual_rad);
        double w_triad = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.triad_residual_rad);

        rs_output.star_weight = w_star;
        rs_output.triad_weight = w_triad;

