        adcs_quat_t weighted_sum;
        weighted_sum.w = w_star * star_normed.w + w_triad * aligned_triad.w;
        weighted_sum.x = w_star * star_normed.x + w_triad * aligned_triad.x;
        weighted_sum.y = w_star * star_normed.y + w_triad * aligned_triad.y;
        weighted_sum.z = w_star * star_normed.z + w_triad * aligned_triad.z;

        adcs_quat_normalize(&weighted_sum, &selected_q);
