    blended.x = -blended.x;
    blended.y = -blended.y;
    blended.z = -blended.z;
}

// Blend
adcs_quat_t prev = rs_state.previous_q_bi;
blended.w = (1.0 - rs_config.output_alpha) * prev.w + rs_config.output_alpha * blended.w;
blended.x = (1.0 - rs_config.output_alpha) * prev.x + rs_config.output_alpha * blended.x;
blended.y = (1.0 - rs_config.output_alpha) * prev.y + rs_config.output_alpha * blended.y;
blended.z = (1.0 - rs_config.output_alpha) * prev.z + rs_config.output_alpha * blended.z;

// Normalize final output
adcs_quat_normalize(&blended, &rs_output.q_bi);

// Update previous attitude
rs_state.previous_q_bi = rs_output.q_bi;

